/* Word Guesser. Loaded on demand by js/arcade.js the first time the game is opened.
   Guess the secret 5-letter word in 6 tries. After each guess the tiles show which letters are right:
   green is the right letter in the right place, gold is in the word but somewhere else, dark is not in the word.
   Solve it and a new word comes. Fewer guesses give more points, and words solved in a row give a streak bonus.
   Every 5th word is a Golden Word, worth double. Miss a word and the game is over.
   Once per word, HINT shows one right letter in its spot (for a few points). */
(() => {
  const { ctx, C, font, shuffle, sfx, setScore, over, tween, pop, shake } = Arcade;

  // The secret words: everyday English words that most people (and kids) know, picked by hand.
  const ANSWERS = 'about above actor adult after again agent agree ahead alarm album alert alien alike alive allow alone along angel anger angle angry ankle apart apple apply apron arena argue arise armor arrow aside attic audio avoid awake award aware awful bacon badge badly baker basic beach beard beast begin being belly below bench berry birth black blade blame blank blast blaze blend bless blind blink block bloom board bonus boost brain brake brave bread break brick bride bring broom brown brush build bunch bunny burst cabin cable camel candy canoe cargo carry catch cause chain chair chalk charm chart chase cheap check cheek cheer chess chest chick chief child chili chill chunk class clean clear click cliff climb clock close cloth cloud clown coach coast cocoa color comet comic coral couch cough count court cover crack craft crane crash crawl crazy cream creek crisp crowd crown crumb crust cubic curve cycle daily dairy daisy dance delay diary dizzy dodge donut dough drama dream dress drill drink drive eagle early earth eight elbow empty enjoy enter error event extra fairy false fancy feast fence ferry fetch fever field fifty fight final flame flash flock flood floor flour flute focus force found frame fresh frost fruit fudge funny gamer ghost giant glass globe glove goofy goose grain grand grape grass great greed green greet grill group guard guess guest guide habit happy heart heavy hedge hello hippo hobby honey honor horse hotel house human humor hurry igloo image jelly jewel jolly judge juice juicy jumbo kayak kebab kitty knife knock koala label laser laugh learn lemon level light limit llama loose lucky lunar lunch magic major mango maple march match mayor medal melon merry metal meter model money month moose motor mouse mouth movie muddy music never night ninja noise north nurse ocean offer often olive onion opera orbit order otter paint panda paper party pasta patch peace peach pearl pedal penny phone photo piano piece pilot pizza place plane plant plate plush point polar porch pouch pound power press price pride print prize proud punch puppy queen quest quick quiet quilt quote radar radio rainy rally ranch rapid raven razor reach ready relax remix reply rhyme rider right river roast robin robot rocky rodeo rough round royal rugby ruler rusty salad salsa sauce scale scarf scene scoop score scout shade shake shape share shark sharp sheep sheet shelf shell shine shiny shirt shock shore short shout shrub sight silly skate skill skirt skull sleep slice slide slope smart smell smile smoke snack snail snake sneak snowy solar solid solve sound south space spark speak speed spell spend spice spike spoon sport spray squad stack stage stair stamp stand start steam steel stick still stone stool storm story stove straw strip stuck study style sugar sunny super sushi swamp sweat sweep sweet swing sword table taste teach teddy teeth thank theme thick thief thing think thorn three throw thumb tiger timer toast today token topic torch total touch tough towel tower track trade trail train treat trick truck truly trunk trust truth tulip tutor twist uncle under until upset video virus visit voice wagon waist watch water whale wheat wheel where while white whole windy witch woman world worry wound wrist write wrong young yummy zebra'.split(' ');
  // Every word that counts as a guess (from the MIT-licensed "word-list" package by Sindre Sorhus), packed 5 letters at a time.
  const PACKED = '';
  let dict = null;
  const isWord = (w) => {
    if (!dict) { dict = new Set(ANSWERS); for (let i = 0; i < PACKED.length; i += 5) dict.add(PACKED.slice(i, i + 5)); }
    return dict.has(w);
  };

  const W = 400, H = 620, ROWS = 6, LEN = 5, TILE = 52, GAP = 6;
  const GX = (W - (LEN * TILE + (LEN - 1) * GAP)) / 2, GY = 54;
  const GREEN = '#3f9a5c', GOLD = '#d1a33a', GREY = '#3b3452', EDGE = '#3a3052';
  const KEYS = ['QWERTYUIOP', 'ASDFGHJKL', '>ZXCVBNM<']; // > is Enter, < is Backspace.
  const KW = 34, KH = 50, KG = 5, KY = 440;
  const HINT_COST = 5, GOLDEN_EVERY = 5;
  const HINT = { x: 308, y: 6, w: 84, h: 38 }; // The HINT button, top right.
  const RANK = { absent: 1, present: 2, correct: 3 };
  const FILL = { absent: GREY, present: GOLD, correct: GREEN };

  // Marks each letter of a guess, counting repeated letters the fair way.
  function score(guess, answer) {
    const res = Array(LEN).fill('absent'), left = {};
    for (let i = 0; i < LEN; i++) { if (guess[i] === answer[i]) res[i] = 'correct'; else left[answer[i]] = (left[answer[i]] || 0) + 1; }
    for (let i = 0; i < LEN; i++) if (res[i] !== 'correct' && left[guess[i]]) { res[i] = 'present'; left[guess[i]]--; }
    return res;
  }

  const words = {
    W, H, color: 'var(--gold)', title: 'Word Guesser', label: 'Score', typing: true,
    intro: 'Guess the 5-letter word in 6 tries. Green: right spot. Gold: in the word. Stuck? Tap HINT. Solve words in a row for a streak bonus, and every 5th word is a Golden Word worth double!',
    hint: 'Type a word and press <kbd>Enter</kbd>, or tap the letters. <kbd>Space</kbd> or the HINT button for a hint. <kbd>Esc</kbd> to leave',
    reset() {
      this.deck = shuffle(ANSWERS.slice()); this.score = 0; this.solved = 0; this.wordN = 0; this.t = 0;
      this.streak = 0; this.streakPop = { s: 1 }; this.flash = { a: 0, c: '209,163,58' }; this.hintBtn = { a: 0 };
      this.ptr = null; this.later = null; this.newWord();
    },
    newWord() {
      this.answer = this.deck[this.wordN % this.deck.length]; this.wordN++;
      this.hintAt = -1; // Which spot HINT showed (-1: no hint yet for this word).
      this.golden = this.wordN % GOLDEN_EVERY === 0;
      this.rows = Array.from({ length: ROWS }, () => ({ text: '', marks: null, flip: [], hop: [], dx: 0 }));
      this.row = 0; this.busy = false; this.keyState = {}; this.msg = ''; this.msgA = { a: 0, s: 1 };
      this.keyPop = {}; this.burst = []; // Looks only: keys that bounce when they change colour, and confetti when a word is solved.
      this.pulse = Array.from({ length: LEN }, () => ({ s: 1 }));
      this.show = { a: 0 }; tween(this.show, { a: 1 }, 350, { ease: 'out' });
      if (this.golden) {
        this.say('GOLDEN WORD!  x2 POINTS', 1800);
        this.flash = { a: 0.3, c: '255,215,90' }; tween(this.flash, { a: 0 }, 600, { ease: 'out' });
        sfx.tone(784, 0.08, 'triangle', 0.05); sfx.tone(1047, 0.14, 'triangle', 0.05);
      }
    },
    say(text, ms = 1400) {
      this.msg = text; this.msgA = { a: 1, s: 0.4 };
      tween(this.msgA, { s: 1 }, 420, { ease: 'back' }); // Pops in, then fades away.
      tween(this.msgA, { a: 0 }, 400, { delay: ms, ease: 'in' });
    },
    // Shows one letter of the word in its right spot: the first spot not already found green.
    // Picked in order (not at random), so the Daily Challenge stays the same for everyone.
    useHint() {
      if (this.busy || this.row >= ROWS) return;
      if (this.hintAt >= 0) { this.say('One hint per word'); return; }
      const found = Array(LEN).fill(false);
      this.rows.forEach((r) => { if (r.marks) r.marks.forEach((m, i) => { if (m === 'correct') found[i] = true; }); });
      const at = found.indexOf(false);
      if (at < 0) { this.say('You already have every letter!'); return; }
      this.hintAt = at;
      const ch = this.answer[at];
      this.score = Math.max(0, this.score - HINT_COST); setScore(this.score);
      if (RANK[this.keyState[ch]] !== RANK.correct) { this.keyState[ch] = 'correct'; const kp = this.keyPop[ch] = { s: 1.4 }; tween(kp, { s: 1 }, 380, { ease: 'back' }); }
      this.hintBtn = { a: 1 }; tween(this.hintBtn, { a: 0 }, 500, { ease: 'out' });
      this.say('Letter ' + (at + 1) + ' is ' + ch.toUpperCase());
      sfx.tone(660, 0.05, 'triangle', 0.05); sfx.tone(880, 0.08, 'triangle', 0.05);
    },
    type(ch) {
      if (this.busy || this.row >= ROWS) return;
      const r = this.rows[this.row];
      if (ch === '<') { if (r.text.length) { r.text = r.text.slice(0, -1); sfx.tone(300, 0.03, 'square', 0.02); } return; }
      if (ch === '>') { this.enter(); return; }
      if (r.text.length >= LEN) return;
      r.text += ch.toLowerCase();
      const p = this.pulse[r.text.length - 1]; p.s = 1.14; tween(p, { s: 1 }, 160, { ease: 'out' });
      sfx.tone(520, 0.03, 'square', 0.02);
    },
    enter() {
      const r = this.rows[this.row];
      if (r.text.length < LEN) { this.wobble(r); this.say('Not enough letters'); return; }
      if (!isWord(r.text)) { this.wobble(r); this.say('Not in the word list'); return; }
      r.marks = score(r.text, this.answer);
      r.flip = r.marks.map(() => ({ f: 0 }));
      this.busy = true;
      r.flip.forEach((f, i) => tween(f, { f: 1 }, 300, { delay: i * 200, ease: 'inout', done: () => {
        sfx.tone([330, 440, 554][RANK[r.marks[i]] - 1], 0.06, 'triangle', 0.05);
        if (i === LEN - 1) this.judge(r);
      } }));
    },
    // 48 little squares fly up out of the solved row and fall away. Spread evenly (not random), so the
    // Daily Challenge's random numbers stay the same for everyone.
    confetti(y, more) {
      const cols = this.golden ? [GOLD, '#ffd75a', C.ink, C.amber] : [GREEN, GOLD, C.ink, C.cyan, C.pink];
      if (more) { // A second, wider burst from both sides of the screen.
        for (let i = 0; i < 32; i++) {
          const left = i % 2 === 0, ang = left ? -1.0 - (i % 8) * 0.08 : -Math.PI + 1.0 + (i % 8) * 0.08, sp = 220 + (i * 29 % 120);
          const b = { x: left ? 10 : W - 10, y: y + 40, dx: Math.cos(ang) * sp, dy: Math.sin(ang) * sp, k: 0, c: cols[i % cols.length], r: i, big: i % 2 === 0 };
          this.burst.push(b);
          tween(b, { k: 1 }, 1300, { ease: 'linear', done: () => { this.burst = this.burst.filter((q) => q !== b); } });
        }
        return;
      }
      for (let i = 0; i < 48; i++) {
        const ang = -Math.PI / 2 + ((i % 16) / 15 - 0.5) * 2.8, sp = 110 + (i * 37 % 120);
        const b = { x: W / 2 + ((i * 53) % 240) - 120, y, dx: Math.cos(ang) * sp, dy: Math.sin(ang) * sp, k: 0, c: cols[i % cols.length], r: i, big: i % 3 === 0 };
        this.burst.push(b);
        tween(b, { k: 1 }, 1200, { ease: 'linear', done: () => { this.burst = this.burst.filter((q) => q !== b); } });
      }
    },
    wobble(r) { sfx.hit(); r.dx = 1; tween(r, { dx: 0 }, 420, { ease: 'out' }); },
    judge(r) {
      r.text.split('').forEach((ch, i) => {
        const k = r.marks[i];
        if (!this.keyState[ch] || RANK[k] > RANK[this.keyState[ch]]) {
          this.keyState[ch] = k;
          const kp = this.keyPop[ch] = { s: 1.35 }; tween(kp, { s: 1 }, 380, { delay: i * 40, ease: 'back' });
        }
      });
      if (r.text === this.answer) {
        const guesses = this.row + 1;
        this.streak++;
        const bonus = this.streak >= 2 ? Math.min(this.streak - 1, 5) * 5 : 0; // 5 more points for each word in a row, up to 25.
        const pts = ((ROWS + 1 - guesses) * 10 + bonus) * (this.golden ? 2 : 1);
        this.score += pts; this.solved++; setScore(this.score);
        this.say(['GENIUS!', 'AMAZING!', 'GREAT!', 'NICE!', 'GOOD!', 'PHEW!'][guesses - 1], 900);
        pop(W / 2, GY + this.row * (TILE + GAP) - 6, '+' + pts, C.lime, 14);
        if (this.streak >= 2) {
          pop(W / 2, GY + this.row * (TILE + GAP) + TILE + 18, this.streak + ' IN A ROW!', C.amber, 12);
          this.streakPop = { s: 1.6 }; tween(this.streakPop, { s: 1 }, 450, { ease: 'back' });
        }
        // Every win flashes the screen; a 1 or 2 guess win or a Golden Word flashes brighter and shakes it.
        const big = guesses <= 2 || this.golden;
        this.flash = { a: big ? 0.5 : 0.22, c: this.golden ? '255,215,90' : '120,220,140' };
        tween(this.flash, { a: 0 }, big ? 800 : 500, { ease: 'out' });
        if (big) shake(4, 260);
        r.hop = Array.from({ length: LEN }, () => ({ y: 0 }));
        r.hop.forEach((h, i) => tween(h, { y: -24 }, 200, { delay: i * 80, ease: 'out', yoyo: true }));
        this.confetti(GY + this.row * (TILE + GAP) + TILE / 2);
        if (big) this.confetti(GY + this.row * (TILE + GAP) + TILE / 2, true);
        sfx.win();
        if (this.golden) [523, 659, 784, 1047].forEach((f, i) => setTimeout(() => sfx.tone(f, 0.1, 'triangle', 0.05), 250 + i * 90));
        this.later = { t: 1.5, fn: () => this.newWord() };
        return;
      }
      this.row++;
      if (this.row >= ROWS) {
        this.streak = 0; shake(5, 300);
        this.say(this.answer.toUpperCase(), 99999);
        this.later = { t: 1.4, fn: () => over(this.score, 'The word was ' + this.answer.toUpperCase() + '. You solved ' + this.solved + ' word' + (this.solved === 1 ? '' : 's') + '.') };
        return;
      }
      this.busy = false;
    },
    key(e, down) {
      if (!down || e.ctrlKey || e.metaKey || e.altKey) return;
      if (e.code === 'Space' || e.key === '?') { e.preventDefault(); if (!e.repeat) this.useHint(); return; }
      if (e.key === 'Enter') { e.preventDefault(); this.type('>'); } else if (e.key === 'Backspace') { e.preventDefault(); this.type('<'); } else if (/^[a-zA-Z]$/.test(e.key)) this.type(e.key);
    },
    point(p) { this.ptr = p; },
    tap() {
      const p = this.ptr; if (!p) return;
      if (p.x >= HINT.x - 6 && p.x <= HINT.x + HINT.w + 6 && p.y >= HINT.y - 6 && p.y <= HINT.y + HINT.h + 6) { this.useHint(); return; }
      const k = this.keyAt(p.x, p.y); if (k) { this.type(k); this.pressed = { k, a: 1 }; tween(this.pressed, { a: 0 }, 200); }
    },
    keyRects() {
      if (this.rects) return this.rects;
      const out = [];
      KEYS.forEach((row, ri) => {
        const wide = ri === 2 ? 52 : KW;
        const total = row.split('').reduce((s, k) => s + (k === '>' || k === '<' ? wide : KW), 0) + (row.length - 1) * KG;
        let x = (W - total) / 2;
        for (const k of row) { const w = k === '>' || k === '<' ? wide : KW; out.push({ k, x, y: KY + ri * (KH + 6), w, h: KH }); x += w + KG; }
      });
      return (this.rects = out);
    },
    keyAt(x, y) {
      // A touch just between two keys still counts for the nearest one.
      let best = null, bd = 18;
      for (const r of this.keyRects()) {
        const dx = Math.max(r.x - x, 0, x - r.x - r.w), dy = Math.max(r.y - y, 0, y - r.y - r.h), d = Math.hypot(dx, dy);
        if (d < bd || (d === 0 && bd > 0)) { best = r; bd = d; if (d === 0) break; }
      }
      return best && best.k;
    },
    update(dt) {
      this.t += dt;
      // Waits run on the game's clock, so they also wait while the game is paused.
      if (this.later && (this.later.t -= dt) <= 0) { const fn = this.later.fn; this.later = null; fn(); }
    },
    draw() {
      ctx.fillStyle = C.bg; ctx.fillRect(0, 0, W, H);
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.font = font(9); ctx.fillStyle = C.muted;
      ctx.font = font(8); ctx.fillText('WORD ' + this.wordN + ' · SOLVED ' + this.solved, W / 2, 18);
      if (this.golden) { ctx.fillStyle = '#ffd75a'; ctx.font = font(8); ctx.fillText('- GOLDEN WORD x2 -', W / 2, 36); }
      // The streak, top left. It pops when it grows.
      if (this.streak >= 2) {
        ctx.save(); ctx.translate(50, 25); ctx.scale(this.streakPop.s, this.streakPop.s);
        ctx.fillStyle = C.amber; ctx.fillRect(-42, -19, 84, 38);
        ctx.fillStyle = C.bg; ctx.font = font(8); ctx.fillText('STREAK', 0, -7); ctx.font = font(13); ctx.fillText('x' + this.streak, 0, 9);
        ctx.restore();
      }
      // The HINT button, top right. Dim once used for this word.
      const used = this.hintAt >= 0;
      ctx.fillStyle = used ? '#241d36' : GOLD; ctx.fillRect(HINT.x, HINT.y, HINT.w, HINT.h);
      if (this.hintBtn.a > 0.01) { ctx.fillStyle = 'rgba(255,255,255,' + this.hintBtn.a * 0.5 + ')'; ctx.fillRect(HINT.x, HINT.y, HINT.w, HINT.h); }
      ctx.fillStyle = used ? '#6d6390' : C.bg; ctx.font = font(12);
      ctx.fillText('HINT', HINT.x + HINT.w / 2, HINT.y + HINT.h / 2 + 1);
      ctx.globalAlpha = this.show.a;
      this.rows.forEach((r, ri) => {
        const shakeX = Math.sin(r.dx * 30) * 10 * r.dx;
        for (let i = 0; i < LEN; i++) {
          const x = GX + i * (TILE + GAP) + shakeX, y = GY + ri * (TILE + GAP) + (r.hop[i] ? r.hop[i].y : 0);
          const ch = r.text[i] || '', f = r.flip[i] ? r.flip[i].f : 0, shown = f >= 0.5;
          const sy = r.flip[i] ? Math.abs(Math.cos(f * Math.PI)) : 1;
          const s = ri === this.row && !r.marks && this.pulse[i] ? this.pulse[i].s : 1;
          ctx.save(); ctx.translate(x + TILE / 2, y + TILE / 2); ctx.scale(s, sy * s);
          if (shown) { ctx.fillStyle = FILL[r.marks[i]]; ctx.fillRect(-TILE / 2, -TILE / 2, TILE, TILE); }
          else {
            ctx.fillStyle = '#120e1c'; ctx.fillRect(-TILE / 2, -TILE / 2, TILE, TILE);
            ctx.strokeStyle = this.golden ? (ch ? '#ffd75a' : '#8a6d2a') : ch ? '#6d6390' : EDGE; ctx.lineWidth = 2; ctx.strokeRect(-TILE / 2 + 1, -TILE / 2 + 1, TILE - 2, TILE - 2);
          }
          if (ch) { ctx.fillStyle = C.ink; ctx.font = font(20); ctx.fillText(ch.toUpperCase(), 0, 2); }
          else if (ri === this.row && !r.marks && i === this.hintAt) {
            // The hinted letter shows faintly in its spot until you type there.
            ctx.strokeStyle = GREEN; ctx.lineWidth = 2; ctx.strokeRect(-TILE / 2 + 1, -TILE / 2 + 1, TILE - 2, TILE - 2);
            ctx.globalAlpha *= 0.75; ctx.fillStyle = '#7ad18f'; ctx.font = font(20); ctx.fillText(this.answer[i].toUpperCase(), 0, 2); ctx.globalAlpha = this.show.a;
          }
          ctx.restore();
        }
      });
      ctx.globalAlpha = 1;
      for (const b of this.burst) {
        const t = b.k * 0.9, x = b.x + b.dx * t, y = b.y + b.dy * t + 260 * t * t;
        ctx.globalAlpha = 1 - b.k; ctx.fillStyle = b.c;
        ctx.save(); ctx.translate(x, y); ctx.rotate(b.r + b.k * 8); if (b.big) ctx.fillRect(-6, -4, 12, 8); else ctx.fillRect(-4, -3, 8, 6); ctx.restore();
      }
      ctx.globalAlpha = 1;
      if (this.flash.a > 0.01) { ctx.fillStyle = 'rgba(' + this.flash.c + ',' + this.flash.a + ')'; ctx.fillRect(0, 0, W, H); } // Win flash.
      if (this.msgA.a > 0.01) {
        ctx.globalAlpha = Math.min(1, this.msgA.a * 1.5);
        ctx.save(); ctx.translate(W / 2, 418); ctx.scale(this.msgA.s, this.msgA.s);
        ctx.font = font(11); const tw = ctx.measureText(this.msg).width + 28;
        ctx.fillStyle = C.ink; ctx.fillRect(-tw / 2, -14, tw, 28);
        ctx.fillStyle = C.bg; ctx.fillText(this.msg, 0, 1);
        ctx.restore();
        ctx.globalAlpha = 1;
      }
      for (const r of this.keyRects()) {
        const st = this.keyState[r.k.toLowerCase()];
        const hit = this.pressed && this.pressed.k === r.k ? this.pressed.a : 0;
        const kp = this.keyPop[r.k.toLowerCase()], ks = kp ? kp.s : 1;
        if (ks !== 1) { ctx.save(); ctx.translate(r.x + r.w / 2, r.y + r.h / 2); ctx.scale(ks, ks); ctx.translate(-r.x - r.w / 2, -r.y - r.h / 2); }
        ctx.fillStyle = st ? FILL[st] : '#4a4166';
        if (st === 'absent') ctx.fillStyle = '#1c1729';
        ctx.fillRect(r.x, r.y + hit * 2, r.w, r.h);
        if (hit) { ctx.fillStyle = 'rgba(255,255,255,' + hit * 0.3 + ')'; ctx.fillRect(r.x, r.y + hit * 2, r.w, r.h); }
        ctx.fillStyle = st === 'absent' ? '#6d6390' : C.ink;
        ctx.font = font(r.k === '>' || r.k === '<' ? 8 : 12);
        ctx.fillText(r.k === '>' ? 'ENTER' : r.k === '<' ? 'DEL' : r.k, r.x + r.w / 2, r.y + r.h / 2 + 1 + hit * 2);
        if (ks !== 1) ctx.restore();
      }
      ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
    },
  };

  Arcade.register('words', words);
})();
